// BOM + XML declaration + wrapper-less raw voucher.
const RAW_VOUCHER = '\uFEFF<?xml version="1.0"?><VOUCHER><DATE>20260701</DATE><VCHNUM>X-1</VCHNUM><AMOUNT>1000</AMOUNT></VOUCHER>';

